/**
 * The client-side twin implementation of RGA.
 *
 * It exists because the client has to edit offline (ADR-0001) — which means it has to be able to
 * merge on its own, without the server. This is a deliberately accepted debt: one algorithm, two
 * implementations, two opportunities for a bug.
 *
 * The safeguard against divergence is the corpus of conformance vectors in `conformance/`,
 * generated by the Java tests and replayed by `conformance.test.ts`. CI runs both sides, so
 * divergence cannot pass silently — but it still DOUBLES the cost of every change to the algorithm.
 *
 * The code is deliberately kept close to the structure of the Java version (the same names, the
 * same method order), so that comparing the two on a change is mechanical rather than detective
 * work.
 */

/**
 * A character identifier.
 *
 * `lamport` is a Lamport clock value, not a replica's sequential counter — see
 * `docs/crdt-design.md` section 1. The practical consequence: it is NOT contiguous within a
 * replica, because it jumps when remote operations arrive.
 */
export interface Id {
  readonly replicaId: number
  readonly lamport: number
}

export function id(replicaId: number, lamport: number): Id {
  return { replicaId, lamport }
}

export function idPlus(base: Id, offset: number): Id {
  return { replicaId: base.replicaId, lamport: base.lamport + offset }
}

export function idEquals(a: Id | null, b: Id | null): boolean {
  if (a === null || b === null) return a === b
  return a.replicaId === b.replicaId && a.lamport === b.lamport
}

/**
 * A total order: lamport first, then replicaId as the tie-break.
 *
 * Ties are common — two replicas working concurrently on the same state generate the same lamport.
 * It is `replicaId` that makes the order total without needing an arbiter, which is the entire
 * point of the choice in ADR-0001.
 */
export function compareIds(a: Id, b: Id): number {
  if (a.lamport !== b.lamport) return a.lamport - b.lamport
  return a.replicaId - b.replicaId
}

export function idToString(value: Id): string {
  return `${value.replicaId}@${value.lamport}`
}

/** A contiguous range of one replica's identifiers: [start, start+length). */
export interface Range {
  readonly start: Id
  readonly length: number
}

export interface InsertOp {
  readonly kind: 'insert'
  readonly id: Id
  /** null means an insertion at the start of the document. */
  readonly originLeft: Id | null
  readonly text: string
}

export interface DeleteOp {
  readonly kind: 'delete'
  readonly id: Id
  readonly targets: readonly Range[]
}

/**
 * A place anchored to a CHARACTER, not to a position (CP13).
 *
 * The side matters and is not cosmetic: an anchor "after character X" and one "before character Y"
 * point at the same place in the text XY — until somebody inserts something between them. That
 * difference decides whether formatting grows when you type at its end. The full justification is
 * in `Anchor.java`; this implementation is its twin.
 */
export interface Anchor {
  readonly charId: Id
  readonly side: 'before' | 'after'
}

export function anchorBefore(charId: Id): Anchor {
  return { charId, side: 'before' }
}

export function anchorAfter(charId: Id): Anchor {
  return { charId, side: 'after' }
}

export interface AddMarkOp {
  readonly kind: 'addMark'
  readonly id: Id
  readonly type: string
  readonly value: string | null
  readonly start: Anchor
  readonly end: Anchor
}

export interface RemoveMarkOp {
  readonly kind: 'removeMark'
  readonly id: Id
  readonly type: string
  readonly start: Anchor
  readonly end: Anchor
}

export type Op = InsertOp | DeleteOp | AddMarkOp | RemoveMarkOp

export function isMarkOp(op: Op): op is AddMarkOp | RemoveMarkOp {
  return op.kind === 'addMark' || op.kind === 'removeMark'
}

/** How many clock values an operation consumes: inserting n characters takes n, everything else 1. */
export function opSpan(op: Op): number {
  return op.kind === 'insert' ? op.text.length : 1
}

/**
 * The mark types whose range GROWS when you type right after them.
 *
 * It has to agree with `MarkTypes.java` — divergence would mean the same operation behaving
 * differently in the browser and on the server, that is, the text looking different to its author
 * than to everyone else. The conformance corpus will not catch this, because it concerns operations
 * that already exist, whereas this is a decision made when an operation is CREATED.
 */
const EXPANDING_MARKS = new Set([
  'bold',
  'italic',
  'underline',
  'strike',
  // Block types (CP30) expand for a different reason from bold: they describe a LINE, and typing
  // at the end of a line has to stay in that line. The end anchor sits before the newline, so the
  // growth stops there and a heading cannot swallow the paragraph below it.
  'heading',
  'quote',
  'list',
])

export function markExpandsAtEnd(type: string): boolean {
  return EXPANDING_MARKS.has(type)
}

export function opMaxLamport(op: Op): number {
  return op.id.lamport + opSpan(op) - 1
}

/** What happened to an applied operation — the counterpart of RgaDocument.ApplyResult in Java. */
export type ApplyResult = 'applied' | 'duplicate' | 'buffered'
